// HasRequest applies the HasEdge predicate on the "request" edge.
func HasRequest() predicate.WorkResponseMember {
	return predicate.WorkResponseMember(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, RequestTable, RequestColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRequestWith applies the HasEdge predicate on the "request" edge with a given conditions (other predicates).
func HasRequestWith(preds ...predicate.WorkRequest) predicate.WorkResponseMember {
	return predicate.WorkResponseMember(func(s *sql.Selector) {
		step := newRequestStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkResponseMember) predicate.WorkResponseMember {
	return predicate.WorkResponseMember(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkResponseMember) predicate.WorkResponseMember {
	return predicate.WorkResponseMember(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkResponseMember) predicate.WorkResponseMember {
	return predicate.WorkResponseMember(sql.NotPredicates(p))
}
